package ais.action.master.generic.v2.test;
import ais.action.master.generic.v2.GenericCrudDefinition;
import ais.action.master.generic.v2.adapter.GenericCrudReviewedAdapterFactory;
import ais.action.master.generic.v2.adapter.JournalWorkflowGenericCrudAdapter;
import ais.database.model.akunting.GrupTransaksi;
public final class JournalWorkflowSelfTest{private JournalWorkflowSelfTest(){}public static void main(String[]a){JournalWorkflowGenericCrudAdapter x=new JournalWorkflowGenericCrudAdapter();GenericCrudDefinition d=new GenericCrudDefinition();d.setEntityClass(GrupTransaksi.class);d.setCreateEnabled(true);d.setUpdateEnabled(true);d.setDeleteEnabled(true);d.setImportEnabled(true);x.configure(d);check(!d.isCreateEnabled()&&!d.isUpdateEnabled()&&!d.isDeleteEnabled()&&!d.isImportEnabled(),"generic mutation must fail closed");check(x.getNaturalKeyProperties().size()==1&&"kode".equals(x.getNaturalKeyProperties().get(0)),"journal natural key");check(GenericCrudReviewedAdapterFactory.isReviewed(GrupTransaksi.class),"reviewed journal adapter");System.out.println("JournalWorkflowSelfTest OK");System.exit(0);}private static void check(boolean v,String m){if(!v)throw new IllegalStateException(m);}}
